import { useEffect, useState } from 'react'
import { Webhook, FileCode, Copy, Check } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { Hook } from '@/types'

interface HookDetailProps {
  hook: Hook | null
  repoPath: string
}

export default function HookDetail({ hook, repoPath }: HookDetailProps) {
  const [content, setContent] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)
  const [copied, setCopied] = useState(false)

  useEffect(() => {
    if (!hook || !repoPath) {
      setContent(null)
      return
    }

    const fetchContent = async () => {
      setLoading(true)
      try {
        const response = await fetch(
          `/api/hooks/${hook.type}/${encodeURIComponent(hook.name)}/content?repoPath=${encodeURIComponent(repoPath)}`
        )
        if (response.ok) {
          const data = await response.json()
          setContent(data.content)
        } else {
          setContent(null)
        }
      } catch (error) {
        console.error('Error fetching hook content:', error)
        setContent(null)
      } finally {
        setLoading(false)
      }
    }

    fetchContent()
  }, [hook, repoPath])

  const handleCopy = async () => {
    if (content) {
      await navigator.clipboard.writeText(content)
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    }
  }

  if (!hook) {
    return (
      <div className="flex flex-col items-center justify-center h-full text-muted-foreground">
        <Webhook className="h-16 w-16 mb-4 opacity-30" />
        <p className="text-sm">Select a hook to view its content</p>
      </div>
    )
  }

  return (
    <div className="h-full flex flex-col">
      {/* Header */}
      <div className="p-4 border-b border-border">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className={cn(
              'p-2 rounded-lg',
              hook.type === 'plugin' ? 'bg-purple-500/10' : 'bg-orange-500/10'
            )}>
              <FileCode className={cn(
                'h-5 w-5',
                hook.type === 'plugin' ? 'text-purple-500' : 'text-orange-500'
              )} />
            </div>
            <div>
              <h2 className="font-semibold text-lg">{hook.name}</h2>
              <p className="text-sm text-muted-foreground">
                {hook.type === 'plugin' ? 'Plugin Hook' : 'Git Hook'} • {hook.event}
              </p>
            </div>
          </div>
          <div className={cn(
            'text-xs px-3 py-1 rounded-full font-medium',
            hook.type === 'plugin' ? 'bg-purple-500/10 text-purple-500' : 'bg-orange-500/10 text-orange-500'
          )}>
            {hook.type}
          </div>
        </div>

        {hook.matcher && (
          <div className="mt-3 p-2 bg-muted rounded text-sm">
            <span className="text-muted-foreground">Matcher: </span>
            <code className="text-foreground">{hook.matcher}</code>
          </div>
        )}

        <div className="mt-2 text-xs text-muted-foreground">
          <span className="font-medium">Path: </span>
          <code>{hook.path}</code>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-hidden flex flex-col">
        <div className="px-4 py-2 border-b border-border flex items-center justify-between bg-muted/30">
          <span className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
            Content
          </span>
          {content && (
            <button
              onClick={handleCopy}
              className="text-xs text-muted-foreground hover:text-foreground flex items-center gap-1 transition-colors"
            >
              {copied ? (
                <>
                  <Check className="h-3 w-3" />
                  Copied
                </>
              ) : (
                <>
                  <Copy className="h-3 w-3" />
                  Copy
                </>
              )}
            </button>
          )}
        </div>

        <div className="flex-1 overflow-auto p-4">
          {loading ? (
            <div className="flex items-center justify-center h-full">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" />
            </div>
          ) : content ? (
            <pre className="text-sm font-mono whitespace-pre-wrap break-words bg-muted/50 p-4 rounded-lg">
              {content}
            </pre>
          ) : (
            <div className="flex flex-col items-center justify-center h-full text-muted-foreground">
              <p className="text-sm">Unable to load hook content</p>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}
