import React, { useMemo, useState } from 'react';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler,
} from 'chart.js';
import { useTheme } from '../contexts/ThemeContext';
import { getChartOptions } from './charts/chartSetup';
import GradePill from './GradePill';
import { GradientCard } from './ui/GradientCard';
import { QualityCategoryGrid } from './QualityCategoryGrid';
import { QualitySourceBreakdown } from './QualitySourceBreakdown';
import { QualityIssuesList } from './QualityIssuesList';
import { QualityTechnicalDebt } from './QualityTechnicalDebt';
import { QualityRecommendations } from './QualityRecommendations';
import { QualityImprovementPlan } from './QualityImprovementPlan';
import type { QualityRunSummary, QualityRunDetail, ParsedQualityData, ParsedPlanData } from '../types';
import { calculateCategoryScores } from '../utils/qualityScoring';

// Register Chart.js components for Line chart
ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler
);

interface QualityDetailProps {
  runs: QualityRunSummary[];
  selectedRun: QualityRunDetail | null;
}

function formatDate(dateString: string): string {
  const date = new Date(dateString);
  return date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  });
}

function formatShortDate(dateString: string): string {
  const date = new Date(dateString);
  return date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
  });
}

function formatIssueCount(count: number): string {
  return count === 1 ? '1 issue' : `${count} issues`;
}

export function parseQualityData(rawContent: string): ParsedQualityData | null {
  try {
    const jsonMatch = rawContent.match(/```json\n([\s\S]*?)\n```/);
    if (jsonMatch) {
      const parsed: ParsedQualityData = JSON.parse(jsonMatch[1]);

      // Compute categoryScores from issues when not present in JSON
      if (!parsed.categoryScores) {
        parsed.categoryScores = calculateCategoryScores(parsed.issues);
      }

      return parsed;
    }
  } catch (e) {
    console.error('Failed to parse quality data:', e);
  }
  return null;
}

export function parsePlanData(planContent: string): ParsedPlanData | null {
  try {
    const jsonMatch = planContent.match(/```json\n([\s\S]*?)\n```/);
    if (jsonMatch) {
      return JSON.parse(jsonMatch[1]) as ParsedPlanData;
    }
  } catch (e) {
    console.error('Failed to parse plan data:', e);
  }
  return null;
}

const QualityDetail: React.FC<QualityDetailProps> = ({ runs, selectedRun }) => {
  const { resolvedTheme } = useTheme();
  const isDark = resolvedTheme === 'dark';
  const chartTheme = getChartOptions(isDark);
  const [activeTab, setActiveTab] = useState<'run' | 'plan'>('run');

  // Parse the selected run data
  const parsedData = useMemo(() => {
    if (!selectedRun?.rawContent) return null;
    return parseQualityData(selectedRun.rawContent);
  }, [selectedRun?.rawContent]);

  // Parse the improvement plan data
  const parsedPlan = useMemo(() => {
    if (!selectedRun?.planContent) return null;
    return parsePlanData(selectedRun.planContent);
  }, [selectedRun?.planContent]);

  if (runs.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-full py-12 px-4">
        <div className="text-6xl mb-4">📊</div>
        <p className="text-text-secondary text-center">No quality data</p>
        <p className="text-text-tertiary text-sm text-center mt-2">
          Run /quality to analyze your codebase
        </p>
      </div>
    );
  }

  // Sort runs chronologically for chart (runId includes time for same-day ordering)
  const sortedRuns = [...runs].sort((a, b) =>
    a.runId.localeCompare(b.runId)
  );

  // Pad with empty slots to cluster points on the left (minimum 10 slots)
  const minSlots = 10;
  const paddingCount = Math.max(0, minSlots - sortedRuns.length);
  const paddedLabels = [
    ...sortedRuns.map(r => formatShortDate(r.date)),
    ...Array(paddingCount).fill(''),
  ];
  const paddedData = [
    ...sortedRuns.map(r => r.score),
    ...Array(paddingCount).fill(null),
  ];

  // Find index of selected run for highlighting
  const selectedIndex = selectedRun
    ? sortedRuns.findIndex(r => r.runId === selectedRun.runId)
    : -1;

  const chartData = {
    labels: paddedLabels,
    datasets: [
      {
        label: 'Quality Score',
        data: paddedData,
        borderColor: '#3b82f6',
        backgroundColor: 'rgba(59, 130, 246, 0.1)',
        fill: true,
        tension: 0.3,
        pointRadius: sortedRuns.map((_, i) => i === selectedIndex ? 10 : 6),
        pointHoverRadius: 10,
        pointBackgroundColor: sortedRuns.map((r: { score: number }) => {
          const baseColor = r.score >= 90 ? '#10b981' // green
            : r.score >= 80 ? '#3b82f6' // blue
            : r.score >= 70 ? '#f59e0b' // yellow
            : r.score >= 60 ? '#f97316' // orange
            : '#ef4444'; // red
          return baseColor;
        }),
        pointBorderColor: sortedRuns.map((_, i) =>
          i === selectedIndex ? '#fff' : 'transparent'
        ),
        pointBorderWidth: sortedRuns.map((_, i) =>
          i === selectedIndex ? 3 : 0
        ),
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        display: false,
      },
      tooltip: {
        callbacks: {
          label: (context: { dataIndex: number; parsed: { y: number } }) => {
            const run = sortedRuns[context.dataIndex];
            return [
              `Score: ${run.score}`,
              `Grade: ${run.grade}`,
              `Issues: ${run.issueCount}`,
            ];
          },
        },
      },
    },
    scales: {
      x: {
        ticks: {
          color: chartTheme.textColor,
        },
        grid: {
          color: chartTheme.gridColor,
          display: false,
        },
      },
      y: {
        beginAtZero: false,
        min: 0,
        max: 100,
        ticks: {
          color: chartTheme.textColor,
          callback: function(value: string | number) {
            return value;
          },
        },
        grid: {
          color: chartTheme.gridColor,
        },
      },
    },
  };

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Chart Section */}
      <div className="p-4 border-b border-border">
        <h3 className="text-lg font-semibold text-text-primary mb-3">Quality Over Time</h3>
        <div className="h-48">
          <Line data={chartData} options={chartOptions} />
        </div>
      </div>

      {/* Selected Run Details */}
      <div className="flex-1 overflow-auto p-4">
        {selectedRun ? (
          <div className="space-y-6">
            {/* Header Card with Gradient Border */}
            <GradientCard>
              <div className="flex items-center justify-between">
                <div>
                  <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
                    Quality Analysis - {formatDate(selectedRun.date)}
                  </h3>
                  <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                    {formatIssueCount(selectedRun.issueCount)} found across{' '}
                    {parsedData?.issues ? new Set(parsedData.issues.map(i => i.category)).size : 0} categories
                  </p>
                </div>
                <div className="flex items-center gap-4">
                  <GradePill grade={selectedRun.grade} score={selectedRun.score} size="lg" />
                  <div className="flex flex-col gap-0.5 text-xs text-gray-400 dark:text-gray-500">
                    <span className="text-green-600">A:90+</span>
                    <span className="text-blue-600">B:80+</span>
                    <span className="text-yellow-600">C:70+</span>
                    <span className="text-orange-600">D:60+</span>
                    <span className="text-red-600">F:&lt;60</span>
                  </div>
                </div>
              </div>
            </GradientCard>

            {/* Tabs (only when plan is available) */}
            {parsedPlan && (
              <div className="flex border-b border-gray-200 dark:border-gray-700" role="tablist">
                <button
                  role="tab"
                  aria-selected={activeTab === 'run'}
                  onClick={() => setActiveTab('run')}
                  className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
                    activeTab === 'run'
                      ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                      : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
                  }`}
                >
                  Run
                </button>
                <button
                  role="tab"
                  aria-selected={activeTab === 'plan'}
                  onClick={() => setActiveTab('plan')}
                  className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
                    activeTab === 'plan'
                      ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                      : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
                  }`}
                >
                  Plan
                </button>
              </div>
            )}

            {/* Run Tab Content (shown when no plan exists, or when Run tab is active) */}
            {(!parsedPlan || activeTab === 'run') && (
              <div className="space-y-6">
                {/* Source Breakdown */}
                {parsedData?.issues && parsedData.issues.some(i => i.source) && (
                  <div>
                    <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-3">
                      Sources
                    </h4>
                    <QualitySourceBreakdown issues={parsedData.issues} />
                  </div>
                )}

                {/* Category Grid */}
                <div>
                  <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-3">
                    Categories
                  </h4>
                  <QualityCategoryGrid issues={parsedData?.issues} categoryScores={parsedData?.categoryScores} />
                </div>

                {/* Technical Debt Summary */}
                <QualityTechnicalDebt
                  technicalDebt={parsedData?.technicalDebt}
                  issues={parsedData?.issues}
                />

                {/* Issues List */}
                {parsedData?.issues && parsedData.issues.length > 0 && (
                  <div>
                    <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-3">
                      Issues ({parsedData.issues.length})
                    </h4>
                    <QualityIssuesList issues={parsedData.issues} />
                  </div>
                )}

                {/* Recommendations */}
                {(parsedData?.recommendations?.length || parsedData?.structuredRecommendations?.length) && (
                  <div>
                    <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-3">
                      Recommendations ({parsedData.structuredRecommendations?.length || parsedData.recommendations?.length || 0})
                    </h4>
                    <QualityRecommendations
                      recommendations={parsedData.recommendations || []}
                      structuredRecommendations={parsedData.structuredRecommendations}
                    />
                  </div>
                )}
              </div>
            )}

            {/* Plan Tab Content */}
            {parsedPlan && activeTab === 'plan' && (
              <QualityImprovementPlan plan={parsedPlan} />
            )}

          </div>
        ) : (
          <div className="flex flex-col items-center justify-center h-full text-text-secondary">
            <p>Select a run from the sidebar to view details</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default QualityDetail;
