function NpmAuditIcon() {
  return (
    <svg viewBox="0 0 128 128" className={ICON_CLASS} aria-label="npm audit">
      <rect fill="currentColor" width="128" height="128" rx="8" />
      <path fill="white" d="M20 28h88v72H64V42H44v58H20V28z" />
      <path fill="currentColor" d="M76 42v46h16V42H76z" />
    </svg>
  );
}

const SOURCE_CONFIGS: Record<string, SourceConfig> = {
  eslint: {
    label: 'ESLint',
    icon: <EslintIcon />,
    color: 'text-purple-500',
    bgColor: 'bg-purple-500/10',
    isAnalyzer: true,
  },
  typescript: {
    label: 'TypeScript',
    icon: <TypeScriptIcon />,
    color: 'text-blue-500',
    bgColor: 'bg-blue-500/10',
    isAnalyzer: true,
  },
  'npm-audit': {
    label: 'npm audit',
    icon: <NpmAuditIcon />,
    color: 'text-red-500',
    bgColor: 'bg-red-500/10',
    isAnalyzer: true,
  },
  llm: {
    label: 'AI Investigation',
    icon: <Sparkles className={ICON_CLASS} />,
    color: 'text-amber-500',
    bgColor: 'bg-amber-500/10',
    isAnalyzer: false,
  },
};

export function getSourceConfig(source: string): SourceConfig {
  const config = SOURCE_CONFIGS[source];
  if (config) {
    return config;
  }

  return {
    label: source,
    icon: <Terminal className={ICON_CLASS} />,
    color: 'text-gray-500',
    bgColor: 'bg-gray-500/10',
    isAnalyzer: true,
  };
}
