import React, { useState } from 'react';
import { GitCommit, Calendar, User, FileText, Loader2, X, TestTube, RefreshCw } from 'lucide-react';

interface CommitDetails {
  sha: string;
  message: string;
  author: string;
  email: string;
  date: string;
  filesChanged?: number;
}

interface CommitDetailsPopoverProps {
  commitSha: string;
  commitType: 'test' | 'feat' | 'refactor';
  repoId: string;
  children: React.ReactNode;
}

const CommitDetailsPopover: React.FC<CommitDetailsPopoverProps> = ({
  commitSha,
  commitType,
  repoId,
  children
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [commitDetails, setCommitDetails] = useState<CommitDetails | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Helper to get commit type icon
  const getCommitIcon = () => {
    switch (commitType) {
      case 'test':
        return <TestTube className="h-5 w-5" />;
      case 'feat':
        return <GitCommit className="h-5 w-5" />;
      case 'refactor':
        return <RefreshCw className="h-5 w-5" />;
    }
  };

  // Helper to get commit type color
  const getCommitColor = () => {
    switch (commitType) {
      case 'test':
        return 'text-red-600 dark:text-red-400';
      case 'feat':
        return 'text-green-600 dark:text-green-400';
      case 'refactor':
        return 'text-blue-600 dark:text-blue-400';
    }
  };

  // Extract commit title (first line of message) and split prefix from rest
  const getCommitTitle = (message: string) => {
    const firstLine = message.split('\n')[0];
    const match = firstLine.match(/^(test|feat|refactor)(\([^)]+\))?:\s*(.+)$/);

    if (match) {
      const prefix = match[1]; // test, feat, or refactor
      const scope = match[2] || ''; // (scope) if present
      const title = match[3]; // rest of title
      return { prefix, scope, title, hasPrefix: true };
    }

    return { prefix: '', scope: '', title: firstLine, hasPrefix: false };
  };

  const fetchCommitDetails = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`/api/repos/${repoId}/git/commits/${commitSha}`);
      if (!response.ok) {
        throw new Error('Failed to fetch commit details');
      }
      const data = await response.json();
      setCommitDetails(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setLoading(false);
    }
  };

  const handleOpen = (e: React.MouseEvent) => {
    e.stopPropagation(); // Prevent bubbling to parent click handlers (e.g., task row)
    setIsOpen(true);
    if (!commitDetails && !loading) {
      fetchCommitDetails();
    }
  };

  const handleClose = (e?: React.MouseEvent) => {
    e?.stopPropagation(); // Prevent bubbling to parent click handlers
    setIsOpen(false);
  };

  return (
    <>
      <div onClick={handleOpen}>
        {children}
      </div>

      {/* Backdrop */}
      {isOpen && (
        <div
          className="fixed inset-0 bg-black/50 z-40 transition-opacity"
          onClick={handleClose}
        />
      )}

      {/* Slide-over panel */}
      <div
        className={`fixed top-0 right-0 h-full w-96 bg-white dark:bg-dark-bg-primary border-l border-border dark:border-dark-border shadow-xl z-50 transform transition-transform duration-300 ease-in-out ${
          isOpen ? 'translate-x-0' : 'translate-x-full'
        }`}
      >
        <div className="flex flex-col h-full">
          {/* Header - Darker background */}
          <div className="bg-gray-200 dark:bg-gray-900 border-b border-border dark:border-dark-border">
            <div className="flex items-center justify-between p-4">
              <div className="flex items-center gap-2">
                <div className={getCommitColor()}>
                  {getCommitIcon()}
                </div>
                <span className={`font-mono text-sm font-medium ${getCommitColor()}`}>
                  {commitDetails?.sha.substring(0, 7) || commitSha.substring(0, 7)}
                </span>
              </div>
              <button
                onClick={handleClose}
                className="p-1 rounded-md hover:bg-gray-300 dark:hover:bg-gray-800 transition-colors"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            {commitDetails && (() => {
              const parsedTitle = getCommitTitle(commitDetails.message);
              return (
                <div className="px-4 pb-4">
                  <h2 className="text-sm font-semibold">
                    {parsedTitle.hasPrefix ? (
                      <>
                        <span className={getCommitColor()}>{parsedTitle.prefix}</span>
                        {parsedTitle.scope && <span className="text-muted-foreground">{parsedTitle.scope}</span>}
                        <span>: {parsedTitle.title}</span>
                      </>
                    ) : (
                      parsedTitle.title
                    )}
                  </h2>
                </div>
              );
            })()}
          </div>

          {/* Content */}
          <div className="flex-1 overflow-y-auto p-4">
            {loading && (
              <div className="flex items-center justify-center py-12">
                <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
              </div>
            )}
            {error && (
              <div className="text-sm text-destructive">
                <p className="font-medium">Error loading commit</p>
                <p className="text-xs mt-1">{error}</p>
              </div>
            )}
            {commitDetails && (
              <div className="space-y-4">
                <div>
                  <h3 className="text-xs font-semibold text-muted-foreground uppercase mb-2">Commit Message</h3>
                  <p className="text-sm whitespace-pre-wrap">{commitDetails.message}</p>
                </div>
              </div>
            )}
          </div>

          {/* Footer - with HR separator */}
          {commitDetails && (
            <div className="border-t border-border dark:border-dark-border">
              <div className="p-4 space-y-3 text-sm">
                <div className="flex items-start gap-3">
                  <User className="h-4 w-4 text-muted-foreground mt-0.5" />
                  <div className="flex-1 min-w-0">
                    <div className="font-medium truncate">{commitDetails.author}</div>
                    <div className="text-xs text-muted-foreground truncate">{commitDetails.email}</div>
                  </div>
                </div>

                <div className="flex items-center gap-3">
                  <Calendar className="h-4 w-4 text-muted-foreground" />
                  <span className="text-xs">{new Date(commitDetails.date).toLocaleString()}</span>
                </div>

                {commitDetails.filesChanged !== undefined && (
                  <div className="flex items-center gap-3">
                    <FileText className="h-4 w-4 text-muted-foreground" />
                    <span className="text-xs">
                      {commitDetails.filesChanged} {commitDetails.filesChanged === 1 ? 'file' : 'files'} changed
                    </span>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </>
  );
};

export default CommitDetailsPopover;
