import React from 'react';
import { cn } from '@/lib/utils';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Bot, Target } from 'lucide-react';
import type { Agent } from '../types';

interface AgentDetailProps {
  agent: Agent;
}

const AgentDetail: React.FC<AgentDetailProps> = ({ agent }) => {
  const relevancePercent = agent.relevanceScore
    ? Math.round(agent.relevanceScore * 100)
    : null;

  return (
    <div className="p-6 space-y-6 overflow-auto h-full">
      {/* Header */}
      <div className="space-y-4">
        <div className="flex items-start gap-4">
          <div className={cn(
            'p-3 rounded-lg bg-primary/10'
          )}>
            <Bot className="h-6 w-6 text-primary" />
          </div>
          <div className="flex-1">
            <h2 className="text-2xl font-bold">{agent.name}</h2>
            {agent.id !== agent.name && (
              <p className="text-sm text-muted-foreground mt-1">{agent.id}</p>
            )}
          </div>
        </div>

        {/* Description */}
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Description</CardTitle>
          </CardHeader>
          <CardContent>
            {agent.description ? (
              <p className="text-sm">{agent.description}</p>
            ) : (
              <p className="text-sm text-muted-foreground">No description available</p>
            )}
          </CardContent>
        </Card>

        {/* Tags */}
        {agent.tags && agent.tags.length > 0 && (
          <Card>
            <CardHeader>
              <CardTitle className="text-lg">Tags</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex flex-wrap gap-2">
                {agent.tags.map((tag) => (
                  <Badge key={tag} variant="secondary">
                    {tag}
                  </Badge>
                ))}
              </div>
            </CardContent>
          </Card>
        )}

        {/* Relevance Score */}
        {relevancePercent !== null && (
          <Card>
            <CardHeader>
              <CardTitle className="text-lg flex items-center gap-2">
                <Target className="h-4 w-4" />
                Relevance
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex items-center gap-4">
                <div className="flex-1">
                  <div className="h-2 bg-muted rounded-full overflow-hidden">
                    <div
                      className="h-full bg-primary rounded-full transition-all"
                      style={{ width: `${relevancePercent}%` }}
                    />
                  </div>
                </div>
                <span className="text-lg font-semibold">{relevancePercent}%</span>
              </div>
              <p className="text-xs text-muted-foreground mt-2">
                Relevance to your current project based on tech stack analysis
              </p>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
};

export default AgentDetail;
