import React, { useState } from 'react';
import { BarChart3, Loader2 } from 'lucide-react';
import GradePill from './GradePill';
import { Button } from './ui/button';
import { Tooltip, TooltipTrigger, TooltipContent } from './ui/tooltip';
import { SkillInvocationPanel } from './SkillInvocationPanel';
import { useSkillInvocation } from '../hooks/useSkillInvocation';
import { useApiKeyStatus } from '../hooks/useApiKeyStatus';
import type { QualityRunSummary } from '../types';

interface QualityListProps {
  runs: QualityRunSummary[];
  selectedRunId: string | null;
  onSelectRun: (runId: string) => void;
  repoId?: string;
}

function formatRunLabel(dateString: string, runId: string): string {
  const date = new Date(dateString);
  const formatted = date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  });

  // Nested format runIds contain time: e.g. 2024-01-15T10-46
  const timeMatch = runId.match(/T(\d{2})-(\d{2})$/);
  if (timeMatch) {
    const hours = parseInt(timeMatch[1], 10);
    const minutes = timeMatch[2];
    return `${formatted} ${hours}:${minutes}`;
  }

  return formatted;
}

function formatIssueCount(count: number): string {
  return count === 1 ? '1 issue' : `${count} issues`;
}

const QualityList: React.FC<QualityListProps> = ({ runs, selectedRunId, onSelectRun, repoId }) => {
  const [showPanel, setShowPanel] = useState(false);

  const {
    invoke,
    cancel,
    isRunning,
    output,
    toolCalls,
    error
  } = useSkillInvocation();

  const { hasClaudeCli, isLoading: isApiKeyLoading } = useApiKeyStatus();

  const handleRunQuality = () => {
    console.log('[QualityList] handleRunQuality called, invoking quality skill');
    setShowPanel(true);
    const prompt = 'Run a comprehensive quality analysis on this repository';
    invoke('quality', prompt, { repoId });
  };

  const handleClosePanel = () => {
    if (!isRunning) {
      setShowPanel(false);
    }
  };

  if (runs.length === 0) {
    return (
      <>
        <div className="flex flex-col h-full">
          {/* Header */}
          <div className="px-4 py-3 border-b border-border">
            <div className="flex items-center justify-between">
              <div>
                <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300">
                  Quality Runs
                </h3>
                <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">
                  0 runs
                </p>
              </div>
              {!isApiKeyLoading && (
                <Tooltip>
                  <TooltipTrigger asChild>
                    <span>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={handleRunQuality}
                        disabled={!hasClaudeCli || isRunning}
                        className="flex items-center gap-2"
                      >
                        {isRunning ? (
                          <Loader2 className="h-4 w-4 animate-spin" />
                        ) : (
                          <BarChart3 className="h-4 w-4" />
                        )}
                        {isRunning ? 'Running...' : 'Run Quality Analysis'}
                      </Button>
                    </span>
                  </TooltipTrigger>
                  {!hasClaudeCli && (
                    <TooltipContent>
                      Claude CLI required - use the /quality skill in Claude Code instead
                    </TooltipContent>
                  )}
                </Tooltip>
              )}
            </div>
          </div>

          {/* Empty state */}
          <div className="flex-1 flex flex-col items-center justify-center py-12 px-4">
            <div className="text-6xl mb-4">📊</div>
            <p className="text-text-secondary text-center">No quality runs</p>
            <p className="text-text-tertiary text-sm text-center mt-2">
              {hasClaudeCli
                ? 'Click "Run Quality" to analyze your codebase'
                : 'Claude CLI required to run analysis'}
            </p>
          </div>
        </div>

        <SkillInvocationPanel
          isOpen={showPanel}
          onClose={handleClosePanel}
          skillName="quality"
          output={output}
          toolCalls={toolCalls}
          isRunning={isRunning}
          error={error}
          onCancel={cancel}
        />
      </>
    );
  }

  return (
    <>
      <div className="flex flex-col" role="list" aria-label="Quality runs">
        {/* Header */}
        <div className="px-4 py-3 border-b border-border">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300">
                Quality Runs
              </h3>
              <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">
                {runs.length} {runs.length === 1 ? 'run' : 'runs'}
              </p>
            </div>
            {!isApiKeyLoading && (
              <Tooltip>
                <TooltipTrigger asChild>
                  <span>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={handleRunQuality}
                      disabled={!hasClaudeCli || isRunning}
                      className="flex items-center gap-2"
                    >
                      {isRunning ? (
                        <Loader2 className="h-4 w-4 animate-spin" />
                      ) : (
                        <BarChart3 className="h-4 w-4" />
                      )}
                      {isRunning ? 'Running...' : 'Run Quality Analysis'}
                    </Button>
                  </span>
                </TooltipTrigger>
                {!hasClaudeCli && (
                  <TooltipContent>
                    Claude CLI required - use the /quality skill in Claude Code instead
                  </TooltipContent>
                )}
              </Tooltip>
            )}
          </div>
        </div>

        {/* List */}
        <div className="p-3 space-y-2">
          {runs.map((run) => (
            <div
              key={run.runId}
              data-selected={run.runId === selectedRunId}
              className={`p-3 rounded-lg cursor-pointer transition-all ${
                run.runId === selectedRunId
                  ? 'bg-purple-50 dark:bg-purple-900/30 border-2 border-purple-500 ring-2 ring-purple-500/20'
                  : 'bg-surface-secondary hover:bg-surface-highlight border border-transparent'
              }`}
              onClick={() => onSelectRun(run.runId)}
            >
              <div className="flex items-center justify-between mb-2">
                <span className="text-gray-900 dark:text-gray-100 font-medium">
                  {formatRunLabel(run.date, run.runId)}
                </span>
                <GradePill grade={run.grade} />
              </div>
              <div className="flex items-center justify-between text-sm">
                <span className="text-gray-600 dark:text-gray-400">Score: {run.score}</span>
                <span className="text-gray-500 dark:text-gray-500">{formatIssueCount(run.issueCount)}</span>
              </div>
            </div>
          ))}
        </div>
      </div>

      <SkillInvocationPanel
        isOpen={showPanel}
        onClose={handleClosePanel}
        skillName="quality"
        output={output}
        toolCalls={toolCalls}
        isRunning={isRunning}
        error={error}
        onCancel={cancel}
      />
    </>
  );
};

export default QualityList;
