import React from 'react';
import type { StructuredRecommendation } from '../types';

interface QualityRecommendationsProps {
  recommendations: string[];
  structuredRecommendations?: StructuredRecommendation[];
}

// Priority order for sorting (lower index = higher priority)
const PRIORITY_ORDER: Record<string | number, number> = {
  critical: 0,
  1: 0,
  high: 1,
  2: 1,
  medium: 2,
  3: 2,
  low: 3,
  4: 3,
  5: 4,
};

// Priority badge colors
const priorityStyles: Record<string, string> = {
  critical: 'bg-red-200 dark:bg-red-900/50 text-red-800 dark:text-red-300',
  high: 'bg-orange-200 dark:bg-orange-900/50 text-orange-800 dark:text-orange-300',
  medium: 'bg-yellow-200 dark:bg-yellow-900/50 text-yellow-800 dark:text-yellow-300',
  low: 'bg-blue-200 dark:bg-blue-900/50 text-blue-800 dark:text-blue-300',
};

// Effort badge colors
const effortStyles: Record<string, string> = {
  trivial: 'bg-green-200 dark:bg-green-900/50 text-green-800 dark:text-green-300',
  small: 'bg-blue-200 dark:bg-blue-900/50 text-blue-800 dark:text-blue-300',
  medium: 'bg-yellow-200 dark:bg-yellow-900/50 text-yellow-800 dark:text-yellow-300',
  large: 'bg-orange-200 dark:bg-orange-900/50 text-orange-800 dark:text-orange-300',
  epic: 'bg-red-200 dark:bg-red-900/50 text-red-800 dark:text-red-300',
};

// Convert numeric priority to string label
function getPriorityLabel(priority: number | string): string {
  if (typeof priority === 'string') {
    return priority;
  }
  const mapping: Record<number, string> = {
    1: 'critical',
    2: 'high',
    3: 'medium',
    4: 'low',
    5: 'info',
  };
  return mapping[priority] || 'medium';
}

export const QualityRecommendations: React.FC<QualityRecommendationsProps> = ({
  recommendations,
  structuredRecommendations,
}) => {
  // If structuredRecommendations is provided and non-empty, render rich cards
  if (structuredRecommendations && structuredRecommendations.length > 0) {
    // Sort by priority (highest first)
    const sorted = [...structuredRecommendations].sort((a, b) => {
      const orderA = PRIORITY_ORDER[a.priority] ?? 2;
      const orderB = PRIORITY_ORDER[b.priority] ?? 2;
      return orderA - orderB;
    });

    return (
      <div className="space-y-3">
        {sorted.map((rec, idx) => {
          const priorityLabel = getPriorityLabel(rec.priority);
          const priorityStyle = priorityStyles[priorityLabel] || priorityStyles.medium;
          const effortStyle = rec.effort ? (effortStyles[rec.effort] || effortStyles.medium) : null;

          return (
            <div
              key={idx}
              className="p-4 bg-gray-50 dark:bg-gray-800/50 rounded-lg border border-gray-200 dark:border-gray-700"
            >
              {/* Header: priority badge + category */}
              <div className="flex items-center gap-2 mb-2">
                <span className={`px-2 py-0.5 text-xs font-medium rounded ${priorityStyle}`}>
                  {priorityLabel}
                </span>
                <span className="text-xs text-gray-500 dark:text-gray-400">
                  {rec.category}
                </span>
              </div>

              {/* Title */}
              <h4 className="text-sm font-semibold text-gray-900 dark:text-gray-100 mb-1">
                {rec.title}
              </h4>

              {/* Description */}
              {rec.description && (
                <p className="text-sm text-gray-600 dark:text-gray-400 mb-2">
                  {rec.description}
                </p>
              )}

              {/* Metadata footer: effort, hours, score gain */}
              {(rec.effort || rec.effortHours || rec.estimatedScoreGain) && (
                <div className="flex items-center gap-3 text-xs">
                  {rec.effort && effortStyle && (
                    <span className={`px-2 py-0.5 rounded ${effortStyle}`}>
                      {rec.effort}
                    </span>
                  )}
                  {rec.effortHours && (
                    <span className="text-gray-500 dark:text-gray-400">
                      ~{Number.isInteger(rec.effortHours) ? rec.effortHours : rec.effortHours.toFixed(1)}h
                    </span>
                  )}
                  {rec.estimatedScoreGain && rec.estimatedScoreGain > 0 && (
                    <span className="text-green-600 dark:text-green-400 font-medium">
                      +{Number.isInteger(rec.estimatedScoreGain) ? rec.estimatedScoreGain : rec.estimatedScoreGain.toFixed(1)} pts
                    </span>
                  )}
                </div>
              )}

              {/* Addressed issues */}
              {rec.addressesIssues && rec.addressesIssues.length > 0 && (
                <div className="mt-2 text-xs text-gray-500 dark:text-gray-400">
                  Addresses issues: {rec.addressesIssues.map(i => `#${i + 1}`).join(', ')}
                </div>
              )}
            </div>
          );
        })}
      </div>
    );
  }

  // Fallback to flat string list (backward compat)
  if (recommendations.length === 0) {
    return null;
  }

  return (
    <div className="space-y-2">
      {recommendations.map((recommendation, idx) => (
        <div
          key={idx}
          className="flex items-start gap-3 p-3 bg-gray-50 dark:bg-gray-800/50 rounded-lg border border-gray-200 dark:border-gray-700"
        >
          <div className="flex items-center justify-center w-6 h-6 rounded-full bg-purple-100 dark:bg-purple-900/30 flex-shrink-0">
            <span className="text-xs font-bold text-purple-600 dark:text-purple-400">
              {idx + 1}
            </span>
          </div>
          <p className="text-sm text-gray-700 dark:text-gray-300 flex-1">
            {recommendation}
          </p>
        </div>
      ))}
    </div>
  );
};

export default QualityRecommendations;
