import React from 'react';
import type { QualityIssue } from '../types';
import { getSourceConfig } from '../utils/sourceIcons';

interface SourceStat {
  readonly source: string;
  readonly count: number;
  readonly severityCounts: {
    readonly critical: number;
    readonly major: number;
    readonly minor: number;
    readonly info: number;
  };
}

function computeSourceStats(issues: ReadonlyArray<QualityIssue>): ReadonlyArray<SourceStat> {
  const map = new Map<string, { count: number; critical: number; major: number; minor: number; info: number }>();

  for (const issue of issues) {
    if (!issue.source) continue;
    const existing = map.get(issue.source);
    if (existing) {
      existing.count++;
      existing[issue.severity]++;
    } else {
      map.set(issue.source, {
        count: 1,
        critical: issue.severity === 'critical' ? 1 : 0,
        major: issue.severity === 'major' ? 1 : 0,
        minor: issue.severity === 'minor' ? 1 : 0,
        info: issue.severity === 'info' ? 1 : 0,
      });
    }
  }

  return Array.from(map.entries())
    .map(([source, data]) => ({
      source,
      count: data.count,
      severityCounts: {
        critical: data.critical,
        major: data.major,
        minor: data.minor,
        info: data.info,
      },
    }))
    .sort((a, b) => b.count - a.count);
}

const SEVERITY_COLORS = {
  critical: 'bg-red-500',
  major: 'bg-orange-500',
  minor: 'bg-yellow-500',
  info: 'bg-blue-400',
} as const;

interface QualitySourceBreakdownProps {
  issues: ReadonlyArray<QualityIssue>;
}

export const QualitySourceBreakdown: React.FC<QualitySourceBreakdownProps> = ({ issues }) => {
  const stats = computeSourceStats(issues);

  if (stats.length === 0) {
    return null;
  }

  return (
    <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
      {stats.map((stat) => {
        const config = getSourceConfig(stat.source);
        const total = stat.count;

        return (
          <div
            key={stat.source}
            data-testid="source-card"
            className="relative rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50 p-3 hover:border-purple-500/50 transition-colors"
          >
            <div className="flex items-center gap-2 mb-2">
              <div className={`flex items-center justify-center w-6 h-6 rounded ${config.bgColor}`}>
                <span className={config.color}>{config.icon}</span>
              </div>
              <span className="text-xs font-medium text-gray-700 dark:text-gray-300 truncate">
                {config.label}
              </span>
            </div>
            <div className="text-sm font-bold text-gray-900 dark:text-gray-100 mb-2">
              {total.toLocaleString()} {total === 1 ? 'issue' : 'issues'}
            </div>
            <div data-testid="severity-bar" className="flex h-1.5 rounded-full overflow-hidden bg-gray-200 dark:bg-gray-700">
              {(['critical', 'major', 'minor', 'info'] as const).map((severity) => {
                const count = stat.severityCounts[severity];
                if (count === 0) return null;
                const pct = (count / total) * 100;
                return (
                  <div
                    key={severity}
                    className={`${SEVERITY_COLORS[severity]}`}
                    style={{ width: `${pct}%` }}
                    title={`${count} ${severity}`}
                  />
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
};
