import React, { useState, useEffect, useCallback } from 'react';
import { Loader2, AlertCircle, Code, TestTube, FileText, Wrench, Play, ChevronDown, ChevronRight, Terminal, Shield, FolderTree } from 'lucide-react';
import type { RepoAnalysisFile } from '../types';
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription } from './ui/sheet';
import { Button } from './ui/button';
import { Tooltip, TooltipTrigger, TooltipContent } from './ui/tooltip';
import { useApiKeyStatus } from '../hooks/useApiKeyStatus';
import { sseManager, type AnalysisChangeEvent, type AnalysisProgressSSEEvent } from '../services/SSEManager';

interface AnalysisPanelProps {
  isOpen: boolean;
  onClose: () => void;
  repoId: string;
}

// Color mapping for tech stack badges
const techColors: Record<string, string> = {
  // Languages
  typescript: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300 border-blue-200 dark:border-blue-800',
  javascript: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300 border-yellow-200 dark:border-yellow-800',
  python: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300 border-green-200 dark:border-green-800',
  go: 'bg-cyan-100 text-cyan-800 dark:bg-cyan-900/30 dark:text-cyan-300 border-cyan-200 dark:border-cyan-800',
  rust: 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-300 border-orange-200 dark:border-orange-800',
  java: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300 border-red-200 dark:border-red-800',
  // Frameworks
  react: 'bg-sky-100 text-sky-800 dark:bg-sky-900/30 dark:text-sky-300 border-sky-200 dark:border-sky-800',
  vue: 'bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-300 border-emerald-200 dark:border-emerald-800',
  angular: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300 border-red-200 dark:border-red-800',
  nextjs: 'bg-gray-800 text-white dark:bg-gray-200 dark:text-gray-900 border-gray-700 dark:border-gray-300',
  hono: 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-300 border-orange-200 dark:border-orange-800',
  express: 'bg-gray-100 text-gray-800 dark:bg-gray-800 dark:text-gray-300 border-gray-200 dark:border-gray-700',
  django: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300 border-green-200 dark:border-green-800',
  // Testing
  jest: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300 border-red-200 dark:border-red-800',
  vitest: 'bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-300 border-emerald-200 dark:border-emerald-800',
  pytest: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300 border-blue-200 dark:border-blue-800',
  mocha: 'bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-300 border-amber-200 dark:border-amber-800',
  // Build tools
  vite: 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300 border-purple-200 dark:border-purple-800',
  webpack: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300 border-blue-200 dark:border-blue-800',
  turbo: 'bg-pink-100 text-pink-800 dark:bg-pink-900/30 dark:text-pink-300 border-pink-200 dark:border-pink-800',
  esbuild: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300 border-yellow-200 dark:border-yellow-800',
  // Package managers
  npm: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300 border-red-200 dark:border-red-800',
  yarn: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300 border-blue-200 dark:border-blue-800',
  pnpm: 'bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-300 border-amber-200 dark:border-amber-800',
  bun: 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-300 border-orange-200 dark:border-orange-800',
  // Linting
  eslint: 'bg-indigo-100 text-indigo-800 dark:bg-indigo-900/30 dark:text-indigo-300 border-indigo-200 dark:border-indigo-800',
};

const getColorForTech = (tech: string): string => {
  const lowerTech = tech.toLowerCase();
  return techColors[lowerTech] || 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300 border-purple-200 dark:border-purple-800';
};

// Analysis progress steps
interface ProgressStep {
  type: string;
  message: string;
  timestamp: string;
}

/** Check if scripts object has any commands */
const hasScripts = (scripts?: RepoAnalysisFile['scripts']): boolean => {
  if (!scripts) return false;
  return !!(scripts.test?.command || scripts.build?.command || scripts.dev?.command || scripts.lint?.command || scripts.e2e?.command);
};

const AnalysisPanel: React.FC<AnalysisPanelProps> = ({
  isOpen,
  onClose,
  repoId,
}) => {
  const [analysis, setAnalysis] = useState<RepoAnalysisFile | null>(null);
  const [agentsMdStatus, setAgentsMdStatus] = useState<{ exists: boolean; lastModified?: string } | null>(null);
  const [exists, setExists] = useState<boolean>(false);
  const [loading, setLoading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [progressSteps, setProgressSteps] = useState<ProgressStep[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [expandedSections, setExpandedSections] = useState<Set<string>>(new Set(['tech-stack', 'test-coverage', 'commands', 'documentation', 'metadata']));

  const { hasClaudeCli } = useApiKeyStatus();

  // Fetch analysis when panel opens
  useEffect(() => {
    if (isOpen && repoId) {
      fetchAnalysis();
    }
    if (!isOpen) {
      setAnalysis(null);
      setExists(false);
      setError(null);
    }
  }, [isOpen, repoId]);

  // Handle SSE analysis events
  const handleAnalysisEvent = useCallback((event: AnalysisChangeEvent) => {
    // Only handle events for this repo
    if (event.repoId !== repoId) return;

    if (event.eventType === 'analysis:complete') {
      setAnalysis(event.analysis ?? null);
      setExists(true);
      setAnalyzing(false);
      setProgressSteps([]);
      setError(null);
      // Re-fetch to get agentsMdStatus from GET endpoint
      fetchAnalysis();
    } else if (event.eventType === 'analysis:failed') {
      setError(event.error || 'Analysis failed');
      setAnalyzing(false);
      setProgressSteps([]);
    }
  }, [repoId]);

  // Handle SSE progress events
  const handleProgressEvent = useCallback((event: AnalysisProgressSSEEvent) => {
    // Only handle events for this repo
    if (event.repoId !== repoId) return;

    setProgressSteps(prev => [...prev, {
      type: event.eventType,
      message: event.message,
      timestamp: event.timestamp
    }]);
  }, [repoId]);

  // Subscribe to SSE events
  useEffect(() => {
    const unsubscribeAnalysis = sseManager.on('analysisChange', (event) => {
      handleAnalysisEvent(event as AnalysisChangeEvent);
    });

    const unsubscribeProgress = sseManager.on('analysisProgress', (event) => {
      handleProgressEvent(event as AnalysisProgressSSEEvent);
    });

    return () => {
      unsubscribeAnalysis();
      unsubscribeProgress();
    };
  }, [handleAnalysisEvent, handleProgressEvent]);

  const fetchAnalysis = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`/api/repos/${repoId}/analysis`);
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `Failed to fetch analysis (${response.status})`);
      }
      const data = await response.json();
      setExists(data.exists);
      setAnalysis(data.analysis);
      setAgentsMdStatus(data.agentsMdStatus ?? null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setLoading(false);
    }
  };

  const runAnalysis = async () => {
    setAnalyzing(true);
    setError(null);
    setProgressSteps([]);
    try {
      const response = await fetch(`/api/repos/${repoId}/analysis`, {
        method: 'POST',
      });
      // 202 Accepted means analysis started - wait for SSE event
      if (response.status === 202) {
        // Analysis is running in background, SSE event will update state
        return;
      }
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `Analysis failed (${response.status})`);
      }
      // For backwards compatibility: if response includes analysis, use it
      const data = await response.json();
      if (data.analysis) {
        setAnalysis(data.analysis);
        setExists(true);
        setAnalyzing(false);
        setProgressSteps([]);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
      setAnalyzing(false);
      setProgressSteps([]);
    }
  };

  const toggleSection = (section: string) => {
    const newExpanded = new Set(expandedSections);
    if (newExpanded.has(section)) {
      newExpanded.delete(section);
    } else {
      newExpanded.add(section);
    }
    setExpandedSections(newExpanded);
  };

  const formatDate = (dateString: string) => {
    try {
      return new Date(dateString).toLocaleDateString('en-GB', {
        day: 'numeric',
        month: 'short',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
      });
    } catch {
      return dateString;
    }
  };

  return (
    <Sheet open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <SheetContent side="right" className="w-[480px] sm:max-w-[480px] overflow-y-auto">
        <SheetHeader>
          <SheetTitle>Repository Analysis</SheetTitle>
          <SheetDescription>
            Tech stack and project structure analysis
          </SheetDescription>
        </SheetHeader>

        <div className="mt-4 space-y-4">
          {/* Run Analysis Button */}
          <div className="flex items-center gap-3">
            <Tooltip>
              <TooltipTrigger asChild>
                <span className="flex-1">
                  <Button
                    onClick={runAnalysis}
                    disabled={!hasClaudeCli || analyzing}
                    className="w-full"
                  >
                    {analyzing ? (
                      <>
                        <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                        Analyzing...
                      </>
                    ) : (
                      <>
                        <Play className="h-4 w-4 mr-2" />
                        Run Analysis
                      </>
                    )}
                  </Button>
                </span>
              </TooltipTrigger>
              {!hasClaudeCli && (
                <TooltipContent>
                  Claude CLI required - use the /analyse command in Claude Code instead
                </TooltipContent>
              )}
            </Tooltip>
          </div>

          {/* Loading State */}
          {loading && (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          )}

          {/* Analysis Progress */}
          {analyzing && progressSteps.length > 0 && (
            <div className="border border-purple-200 dark:border-purple-800 rounded-lg overflow-hidden">
              <div className="bg-purple-50 dark:bg-purple-900/20 px-3 py-2 border-b border-purple-200 dark:border-purple-800">
                <span className="text-sm font-medium text-purple-700 dark:text-purple-300">Analysis Progress</span>
              </div>
              <div className="p-3 space-y-2 max-h-48 overflow-y-auto">
                {progressSteps.map((step, index) => (
                  <div key={index} className="flex items-center gap-2 text-sm">
                    {step.type === 'analysis:failed' ? (
                      <AlertCircle className="h-4 w-4 text-red-500 flex-shrink-0" />
                    ) : step.type === 'analysis:complete' ? (
                      <span className="h-4 w-4 text-green-500 flex-shrink-0">✓</span>
                    ) : index === progressSteps.length - 1 ? (
                      <Loader2 className="h-4 w-4 animate-spin text-purple-500 flex-shrink-0" />
                    ) : (
                      <span className="h-4 w-4 text-green-500 flex-shrink-0">✓</span>
                    )}
                    <span className="text-gray-600 dark:text-gray-300">{step.message}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Error State */}
          {error && (
            <div className="flex items-start gap-3 p-4 bg-red-50 dark:bg-red-900/20 rounded-lg">
              <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0 mt-0.5" />
              <div>
                <p className="font-medium text-red-700 dark:text-red-400">Error</p>
                <p className="text-sm text-red-600 dark:text-red-300 mt-1">{error}</p>
              </div>
            </div>
          )}

          {/* No Analysis State */}
          {!loading && !error && !exists && (
            <div className="flex flex-col items-center justify-center py-12 text-center">
              <Code className="h-12 w-12 text-gray-300 dark:text-gray-600 mb-4" />
              <p className="text-gray-500 dark:text-gray-400 mb-2">
                This repository has not been analysed yet.
              </p>
              <p className="text-sm text-gray-400 dark:text-gray-500">
                Click "Run Analysis" to analyse the tech stack.
              </p>
            </div>
          )}

          {/* Analysis Content */}
          {!loading && !error && exists && analysis && (
            <div className="space-y-4">
              {/* Summary Card */}
              <div className="p-4 rounded-lg bg-gradient-to-r from-purple-50 to-blue-50 dark:from-purple-900/20 dark:to-blue-900/20 border border-purple-100 dark:border-purple-800">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm text-gray-500 dark:text-gray-400">Primary Language</p>
                    <p className="text-lg font-semibold capitalize">{analysis.analysis.primaryLanguage}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-sm text-gray-500 dark:text-gray-400">Last Analysed</p>
                    <p className="text-sm">{formatDate(analysis.detectedAt)}</p>
                  </div>
                </div>
              </div>

              {/* Tech Stack Section */}
              <CollapsibleSection
                title="Tech Stack"
                icon={<Code className="h-4 w-4" />}
                isExpanded={expandedSections.has('tech-stack')}
                onToggle={() => toggleSection('tech-stack')}
              >
                <div className="grid grid-cols-2 gap-4">
                  {analysis.stack.languages.length > 0 && (
                    <div>
                      <span className="text-xs text-gray-500 dark:text-gray-400 block mb-2">Languages</span>
                      <div className="flex flex-wrap gap-1.5">
                        {analysis.stack.languages.map((item, index) => (
                          <TechBadge key={index} tech={item} />
                        ))}
                      </div>
                    </div>
                  )}
                  {analysis.stack.frameworks.length > 0 && (
                    <div>
                      <span className="text-xs text-gray-500 dark:text-gray-400 block mb-2">Frameworks</span>
                      <div className="flex flex-wrap gap-1.5">
                        {analysis.stack.frameworks.map((item, index) => (
                          <TechBadge key={index} tech={item} />
                        ))}
                      </div>
                    </div>
                  )}
                  {analysis.stack.build.length > 0 && (
                    <div>
                      <span className="text-xs text-gray-500 dark:text-gray-400 block mb-2">Build Tools</span>
                      <div className="flex flex-wrap gap-1.5">
                        {analysis.stack.build.map((item, index) => (
                          <TechBadge key={index} tech={item} />
                        ))}
                      </div>
                    </div>
                  )}
                  {analysis.stack.testing.length > 0 && (
                    <div>
                      <span className="text-xs text-gray-500 dark:text-gray-400 block mb-2">Testing</span>
                      <div className="flex flex-wrap gap-1.5">
                        {analysis.stack.testing.map((item, index) => (
                          <TechBadge key={index} tech={item} />
                        ))}
                      </div>
                    </div>
                  )}
                  {analysis.packageManager && (
                    <div>
                      <span className="text-xs text-gray-500 dark:text-gray-400 block mb-2">Package Manager</span>
                      <div className="flex flex-wrap gap-1.5">
                        <TechBadge tech={analysis.packageManager} />
                      </div>
                    </div>
                  )}
                </div>
              </CollapsibleSection>

              {/* Commands Section */}
              {hasScripts(analysis.scripts) && (
                <CollapsibleSection
                  title="Commands"
                  icon={<Terminal className="h-4 w-4" />}
                  isExpanded={expandedSections.has('commands')}
                  onToggle={() => toggleSection('commands')}
                >
                  <div className="space-y-2">
                    {analysis.scripts?.test?.command && (
                      <CommandRow label="Test" command={analysis.scripts.test.command} />
                    )}
                    {analysis.scripts?.build?.command && (
                      <CommandRow label="Build" command={analysis.scripts.build.command} />
                    )}
                    {analysis.scripts?.dev?.command && (
                      <CommandRow label="Dev" command={analysis.scripts.dev.command} />
                    )}
                    {analysis.scripts?.lint?.command && (
                      <CommandRow label="Lint" command={analysis.scripts.lint.command} />
                    )}
                    {analysis.scripts?.e2e?.command && (
                      <CommandRow label="E2E" command={analysis.scripts.e2e.command} />
                    )}
                  </div>
                </CollapsibleSection>
              )}

              {/* Linting & Style Section */}
              {analysis.linting && (
                <CollapsibleSection
                  title="Linting & Style"
                  icon={<Shield className="h-4 w-4" />}
                  isExpanded={expandedSections.has('linting')}
                  onToggle={() => toggleSection('linting')}
                >
                  <div className="space-y-3">
                    {analysis.linting.tool && (
                      <div>
                        <span className="text-xs text-gray-500 dark:text-gray-400 block mb-2">Linter</span>
                        <TechBadge tech={analysis.linting.tool} />
                      </div>
                    )}
                    {analysis.linting.plugins && analysis.linting.plugins.length > 0 && (
                      <div>
                        <span className="text-xs text-gray-500 dark:text-gray-400 block mb-2">Plugins</span>
                        <div className="flex flex-wrap gap-1.5">
                          {analysis.linting.plugins.map((plugin, index) => (
                            <span
                              key={index}
                              className="px-2 py-0.5 text-xs rounded-md border bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-300 border-gray-200 dark:border-gray-700"
                            >
                              {plugin}
                            </span>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                </CollapsibleSection>
              )}

              {/* Test Coverage Section */}
              <CollapsibleSection
                title="Test Coverage"
                icon={<TestTube className="h-4 w-4" />}
                isExpanded={expandedSections.has('test-coverage')}
                onToggle={() => toggleSection('test-coverage')}
              >
                <div className="space-y-2">
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-500 dark:text-gray-400">Has Tests</span>
                    <span className={analysis.analysis.hasTests ? 'text-green-600 dark:text-green-400' : 'text-gray-500'}>
                      {analysis.analysis.hasTests ? 'Yes' : 'No'}
                    </span>
                  </div>
                  {analysis.analysis.hasTests && (
                    <>
                      <div className="flex justify-between text-sm">
                        <span className="text-gray-500 dark:text-gray-400">Test Files</span>
                        <span>{analysis.analysis.testFileCount}</span>
                      </div>
                      {analysis.scripts?.test?.framework && (
                        <div className="flex justify-between text-sm">
                          <span className="text-gray-500 dark:text-gray-400">Framework</span>
                          <span>{analysis.scripts.test.framework}</span>
                        </div>
                      )}
                      {analysis.analysis.testPatterns.length > 0 && (
                        <div className="flex justify-between text-sm">
                          <span className="text-gray-500 dark:text-gray-400">Patterns</span>
                          <span className="text-right font-mono text-xs">{analysis.analysis.testPatterns.join(', ')}</span>
                        </div>
                      )}
                      {analysis.scripts?.test?.coverage && (
                        <div className="flex justify-between text-sm">
                          <span className="text-gray-500 dark:text-gray-400">Coverage</span>
                          <span className="font-mono text-xs">{analysis.scripts.test.coverage}</span>
                        </div>
                      )}
                    </>
                  )}
                </div>
              </CollapsibleSection>

              {/* Project Structure Section */}
              {(analysis.monorepo || (analysis.sourceDirectories && analysis.sourceDirectories.length > 0)) && (
                <CollapsibleSection
                  title="Project Structure"
                  icon={<FolderTree className="h-4 w-4" />}
                  isExpanded={expandedSections.has('project-structure')}
                  onToggle={() => toggleSection('project-structure')}
                >
                  <div className="space-y-3">
                    {analysis.monorepo && (
                      <div>
                        <span className="text-xs text-gray-500 dark:text-gray-400 block mb-2">Monorepo Tool</span>
                        <TechBadge tech={analysis.monorepo.tool || 'workspaces'} />
                        {analysis.monorepo.packages.length > 0 && (
                          <div className="mt-3">
                            <span className="text-xs text-gray-500 dark:text-gray-400 block mb-2">Packages</span>
                            <div className="space-y-1">
                              {analysis.monorepo.packages.map((pkg, index) => (
                                <div key={index} className="text-sm font-mono text-gray-700 dark:text-gray-300">
                                  {pkg}
                                </div>
                              ))}
                            </div>
                          </div>
                        )}
                      </div>
                    )}
                    {analysis.sourceDirectories && analysis.sourceDirectories.length > 0 && (
                      <div>
                        <span className="text-xs text-gray-500 dark:text-gray-400 block mb-2">Source Directories</span>
                        <div className="flex flex-wrap gap-1.5">
                          {analysis.sourceDirectories.map((dir, index) => (
                            <span
                              key={index}
                              className="px-2 py-0.5 text-xs font-mono rounded-md border bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-300 border-gray-200 dark:border-gray-700"
                            >
                              {dir}
                            </span>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                </CollapsibleSection>
              )}

              {/* Documentation Section */}
              {(analysis.analysis.documentationPattern || analysis.analysis.documentationLocations) && (
                <CollapsibleSection
                  title="Documentation"
                  icon={<FileText className="h-4 w-4" />}
                  isExpanded={expandedSections.has('documentation')}
                  onToggle={() => toggleSection('documentation')}
                >
                  <div className="space-y-2">
                    {analysis.analysis.documentationPattern && (
                      <div className="flex justify-between text-sm">
                        <span className="text-gray-500 dark:text-gray-400">Pattern</span>
                        <span className="capitalize">{analysis.analysis.documentationPattern.replace(/-/g, ' ')}</span>
                      </div>
                    )}
                    {analysis.analysis.documentationLocations && analysis.analysis.documentationLocations.length > 0 && (
                      <div className="flex justify-between text-sm">
                        <span className="text-gray-500 dark:text-gray-400">Locations</span>
                        <span className="text-right">{analysis.analysis.documentationLocations.join(', ')}</span>
                      </div>
                    )}
                  </div>
                </CollapsibleSection>
              )}

              {/* Metadata Section */}
              <CollapsibleSection
                title="Metadata"
                icon={<Wrench className="h-4 w-4" />}
                isExpanded={expandedSections.has('metadata')}
                onToggle={() => toggleSection('metadata')}
              >
                <div className="space-y-2">
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-500 dark:text-gray-400">Primary Language</span>
                    <span className="capitalize">{analysis.analysis.primaryLanguage}</span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-500 dark:text-gray-400">Polyglot</span>
                    <span>{analysis.analysis.isPolyglot ? 'Yes' : 'No'}</span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-500 dark:text-gray-400">Analysed</span>
                    <span>{formatDate(analysis.detectedAt)}</span>
                  </div>
                </div>
              </CollapsibleSection>

              {/* AGENTS.md Section */}
              {agentsMdStatus && (
                <CollapsibleSection
                  title="AGENTS.md"
                  icon={<FileText className="h-4 w-4" />}
                  isExpanded={expandedSections.has('agents-md')}
                  onToggle={() => toggleSection('agents-md')}
                >
                  <div className="space-y-2">
                    <div className="flex justify-between text-sm">
                      <span className="text-gray-500 dark:text-gray-400">Status</span>
                      <span className={agentsMdStatus.exists ? 'text-green-600 dark:text-green-400' : 'text-gray-500'}>
                        {agentsMdStatus.exists ? 'Generated' : 'Not Generated'}
                      </span>
                    </div>
                    {agentsMdStatus.exists && agentsMdStatus.lastModified && (
                      <div className="flex justify-between text-sm">
                        <span className="text-gray-500 dark:text-gray-400">Last Modified</span>
                        <span>{formatDate(agentsMdStatus.lastModified)}</span>
                      </div>
                    )}
                  </div>
                </CollapsibleSection>
              )}
            </div>
          )}
        </div>
      </SheetContent>
    </Sheet>
  );
};

// Helper Components
interface CollapsibleSectionProps {
  title: string;
  icon: React.ReactNode;
  isExpanded: boolean;
  onToggle: () => void;
  children: React.ReactNode;
}

const CollapsibleSection: React.FC<CollapsibleSectionProps> = ({
  title,
  icon,
  isExpanded,
  onToggle,
  children
}) => (
  <div className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden">
    <button
      onClick={onToggle}
      className="w-full flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-800/50 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
    >
      <div className="flex items-center gap-2">
        {isExpanded ? (
          <ChevronDown className="h-4 w-4 text-gray-500" />
        ) : (
          <ChevronRight className="h-4 w-4 text-gray-500" />
        )}
        {icon}
        <span className="font-medium text-sm">{title}</span>
      </div>
    </button>
    {isExpanded && (
      <div className="p-3 bg-white dark:bg-gray-900">
        {children}
      </div>
    )}
  </div>
);

interface TechBadgeProps {
  tech: string;
}

const TechBadge: React.FC<TechBadgeProps> = ({ tech }) => (
  <span
    className={`px-2 py-0.5 text-sm rounded-md border ${getColorForTech(tech)}`}
  >
    {tech}
  </span>
);

interface CommandRowProps {
  label: string;
  command: string;
}

const CommandRow: React.FC<CommandRowProps> = ({ label, command }) => (
  <div className="flex justify-between items-center text-sm">
    <span className="text-gray-500 dark:text-gray-400">{label}</span>
    <span className="font-mono text-xs bg-gray-100 dark:bg-gray-800 px-2 py-1 rounded">
      {command}
    </span>
  </div>
);

export default AnalysisPanel;
