import type { GroupedPersonasData, LibraryPersona } from '../types';

const API_BASE = '/api';

export async function fetchGroupedPersonas(): Promise<GroupedPersonasData> {
  const response = await fetch(`${API_BASE}/personas`);
  if (!response.ok) {
    throw new Error('Failed to fetch personas');
  }
  return response.json();
}

export async function fetchLibraryPersonas(): Promise<{ personas: LibraryPersona[] }> {
  const response = await fetch(`${API_BASE}/personas/library`);
  if (!response.ok) {
    throw new Error('Failed to fetch library personas');
  }
  return response.json();
}

export async function fetchLibraryPersonasWithToken(token: string): Promise<{ personas: LibraryPersona[] }> {
  const response = await fetch(`${API_BASE}/library/personas`, {
    headers: {
      'Authorization': `Bearer ${token}`
    }
  });
  if (!response.ok) {
    throw new Error('Failed to fetch library personas');
  }
  return response.json();
}

